 import scipy; print('scipy',scipy.__version__)
except ImportError: print('numpy only')
import json,numpy as np
rs=json.load(open('/app/length_results.json'))['results']
y=np.array([r['proxy_reward'] for r in rs if r['config']['method']=='ppo'])
p=np.array([r['config']['len_pen'] for r in rs if r['config']['method']=='ppo'])
best=None
for t in np.linspace(.1,30,10000):
 x=1-np.exp(-t/(1+p))
 A=np.array([np.ones(len(x)),x]).T
 coeff=np.linalg.lstsq(A,y,rcond=None)[0]
 err=np.mean((y-A@coeff)**2)
 if best is None or err<best[0]:best=(err,t,coeff)
print('exponential fit MSE, scale, quality/length',best, 'fraction',best[2][1]*(1-np.exp(-best[1]))/sum(best[2]))
